  letter-spacing: -0.01em;
}

.lede {
  margin: 0 0 1.5rem;
  color: var(--text-muted);
}

.required-legend {
  margin: 0 0 1.25rem;
  font-size: 0.875rem;
  color: var(--text-muted);
}
.required-legend .req,
.req {
  color: var(--danger);
  margin-left: 2px;
}

.form-field {
  margin-bottom: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-field label {
  font-weight: 600;
  font-size: 0.95rem;
}

.optional {
  color: var(--text-muted);
  font-weight: 400;
  font-size: 0.85rem;
  margin-left: 4px;
}

.form-field input {
  width: 100%;
  padding: 0.7rem 0.85rem;
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}

.form-field input::placeholder {
  color: var(--text-muted);
}

.form-field input:hover {
  border-color: #5b6472;
}

.form-field input:focus {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
  background: #232b36;
}

.help-text {
  margin: 0;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.submit-btn {
  margin-top: 0.5rem;
  width: 100%;
  padding: 0.8rem 1.25rem;
  background: var(--accent);
  color: var(--accent-fg);
  border: 1px solid transparent;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}
.submit-btn:hover { background: var(--accent-hover); }
.submit-btn:active { transform: translateY(1px); }
.submit-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
